from pysat.card import CardEnc, EncType
from pysat.formula import IDPool
import itertools

w, g, s = 7, 6, 3
n = g * s

vpool = IDPool()

def var(week, golfer, group):
    return vpool.id(f"v_{week}_{golfer}_{group}")

solver = Glucose4()

for i in range(w):
    for j in range(n):
        solver.add_clause([var(i, j, k) for k in range(g)])
        for k1, k2 in itertools.combinations(range(g), 2):
            solver.add_clause([-var(i, j, k1), -var(i, j, k2)])

for i in range(w):
    for k in range(g):
        lits = [var(i, j, k) for j in range(n)]
        cnf = CardEnc.equals(lits=lits, bound=s, encoding=EncType.seqcounter, vpool=vpool)
        for clause in cnf.clauses:
            solver.add_clause(clause)

for j1, j2 in itertools.combinations(range(n), 2):
    for i1, i2 in itertools.combinations(range(w), 2):
        for k1 in range(g):
            for k2 in range(g):
                solver.add_clause([-var(i1, j1, k1), -var(i1, j2, k1), -var(i2, j1, k2), -var(i2, j2, k2)])

# Symmetry breaking
# Week 0: golfer j is in group j // s
for j in range(n):
    solver.add_clause([var(0, j, j // s)])

# Golfer 0 is in group 0 every week
for i in range(w):
    solver.add_clause([var(i, 0, 0)])

# Week 1: golfers 1, 2, 3, 4, 5 are in groups 0, 1, 2, 3, 4
# Wait, golfer 0 is in group 0.
# In week 0, group 0 is {0, 1, 2}.
# In week 1, they must be in different groups.
# Golfer 0 is in group 0. So golfer 1 can be in group 1, golfer 2 in group 2.
solver.add_clause([var(1, 1, 1)])
solver.add_clause([var(1, 2, 2)])

# In week 0, group 1 is {3, 4, 5}.
# In week 1, they must be in different groups.
# We can put golfer 3 in group 0, golfer 4 in group 1, golfer 5 in group 2.
# Wait, golfer 3 in group 0 is fine.
solver.add_clause([var(1, 3, 0)])
solver.add_clause([var(1, 4, 3)])
solver.add_clause([var(1, 5, 4)])

print("Solving...")
if solver.solve():
    print("SAT")
    model = solver.get_model()
    res = []
    for i in range(w):
        for j in range(n):
            for k in range(g):
                if model[abs(var(i, j, k)) - 1] > 0:
                    res.append(k)
    print(res)
else:
    print("UNSAT")

def check_solution(res, w, g, s):
    n = g * s
    if len(res) != w * n:
        return False

    # Check each week
    for i in range(w):
        groups = [[] for _ in range(g)]
        for j in range(n):
            groups[res[i * n + j]].append(j)
        for k in range(g):
            if len(groups[k]) != s:
                print(f"Week {i} group {k} has {len(groups[k])} golfers")
                return False

    # Check pairs
    pairs = set()
    for i in range(w):
        groups = [[] for _ in range(g)]
        for j in range(n):
            groups[res[i * n + j]].append(j)
        for k in range(g):
            for j1 in range(s):
                for j2 in range(j1 + 1, s):
                    p = tuple(sorted([groups[k][j1], groups[k][j2]]))
                    if p in pairs:
                        print(f"Pair {p} repeated")
                        return False
                    pairs.add(p)
    return True

